<?php
use App\Http\Controllers\Auth\OtpLoginController; use App\Http\Controllers\DashboardController; use App\Http\Controllers\ReconciliationController; use App\Http\Controllers\TransactionController; use App\Http\Controllers\UserController; use Illuminate\Support\Facades\Route;
Route::middleware('guest')->group(function(){Route::get('/login',[OtpLoginController::class,'show'])->name('login');Route::post('/login/code',[OtpLoginController::class,'requestCode'])->middleware('throttle:5,1')->name('otp.request');Route::get('/login/verify',[OtpLoginController::class,'showVerify'])->name('otp.verify');Route::post('/login/verify',[OtpLoginController::class,'verify'])->middleware('throttle:10,1')->name('otp.check');});
Route::post('/logout',[OtpLoginController::class,'logout'])->middleware('auth')->name('logout');
Route::middleware('auth')->group(function(){Route::get('/',DashboardController::class)->name('dashboard');Route::get('/transactions/{type}',[TransactionController::class,'index'])->whereIn('type',['sale','expense','transfer'])->name('transactions.index');Route::post('/transactions',[TransactionController::class,'store'])->name('transactions.store');Route::delete('/transactions/{transaction}',[TransactionController::class,'destroy'])->name('transactions.destroy');Route::post('/reconciliation',[ReconciliationController::class,'store'])->name('reconciliation.store');Route::middleware('role:admin')->group(function(){Route::get('/users',[UserController::class,'index'])->name('users.index');Route::post('/users',[UserController::class,'store'])->name('users.store');Route::patch('/users/{user}',[UserController::class,'update'])->name('users.update');});});
